// Returns the class index; prob (optional) gets the share of votes for each class.
static inline int act_predict(const float *x, float *prob) {
  float p[ACT_N_CLASSES] = {0};
  act_tree_0(x, p);
  act_tree_1(x, p);
  act_tree_2(x, p);
  act_tree_3(x, p);
  act_tree_4(x, p);
  act_tree_5(x, p);
  act_tree_6(x, p);
  act_tree_7(x, p);
  act_tree_8(x, p);
  act_tree_9(x, p);
  int best = 0;
  for (int k = 0; k < ACT_N_CLASSES; k++) {
    p[k] /= 10.0f;
    if (p[k] > p[best]) best = k;
    if (prob) prob[k] = p[k];
  }
  return best;
}
